  public func traceySubscribeUpdates(updates: UnboundTx<TraceyDataUpdate>) async throws {
    var channelIds: [UInt64] = []
    let updatesWireIndex = channelIds.count
    // r[impl schema.exchange.channels.tx-args]
    channelIds.append(
      await connection.bindClientTxArg(
        updates,
        deserialize: { (buf) throws -> TraceyDataUpdate in
          let bytes = buf.readBytes(length: buf.readableBytes) ?? []
          guard
            let decoder = self.connection.schemaReceiveTracker.buildAuxiliaryDecodeFn(
              0x95cb_0e42_5a7a_49a0, .args, role: "channel.arg.0.tx.element",
              readerDescriptor: testbed_traceySubscribeUpdates_updates_ElementDescriptor,
              readerBlocks: testbed_traceySubscribeUpdates_updates_ElementDescriptorBlocks,
              local: testbedRegistry)
          else { throw VoxError<Infallible>.invalidPayload("no channel element schema advertised") }
          return try decodeVoxTyped(decoder, bytes)
        }))
    let payload = encodeVoxTyped(
      Data(channelWireIndexBytes(updatesWireIndex)), testbed_traceySubscribeUpdates_ArgsEncoder)
    let response = try await connection.call(
      methodId: 0x95cb_0e42_5a7a_49a0, metadata: .null, payload: payload, channels: channelIds,
      timeout: timeout,
      finalizeChannels: { finalizeChannel(updates) },
      schemaInfo: ClientSchemaInfo(
        methodSchemas: testbedMethods[0x95cb_0e42_5a7a_49a0]!, registry: testbedRegistry))
    guard
      let respDecoder = connection.schemaReceiveTracker.buildDecodeFn(
        0x95cb_0e42_5a7a_49a0, .response,
        readerDescriptor: testbed_traceySubscribeUpdates_ResponseDescriptor,
        readerBlocks: testbed_traceySubscribeUpdates_ResponseDescriptorBlocks,
        local: testbedRegistry)
    else {
      throw VoxError<Infallible>.invalidPayload("no response schema advertised")
    }
    let result: Result<Void, VoxError<Infallible>> = try decodeVoxTyped(respDecoder, response)
    switch result {
    case .success: return
    case .failure(let error): throw error
    }
  }

