public final class TestbedDispatcher: ServiceDispatcher {
  private let handler: TestbedHandler
  public init(handler: TestbedHandler) { self.handler = handler }

  public func encodeVoxError(_ error: VoxRuntimeError) -> [UInt8] {
    let wire: VoxError<Infallible>
    switch error {
    case .unknownMethod, .notImplemented: wire = .unknownMethod
    case .invalidPayload(let s), .decodeError(let s), .encodeError(let s): wire = .invalidPayload(s)
    case .cancelled: wire = .cancelled
    case .connectionClosed: wire = .connectionClosed
    case .timeout: wire = .timedOut
    case .indeterminate: wire = .indeterminate
    }
    let r: Result<String, VoxError<Infallible>> = .failure(wire)
    return encodeVoxTyped(r, testbed_echo_ResponseEncoder)
  }

  public func preregister(
    methodId: UInt64, payload: [UInt8], channels: [UInt64], registry: ChannelRegistry
  ) async {
    for id in channels { await registry.markKnown(id) }
  }

  public func dispatch(
    methodId: UInt64, payload: [UInt8], requestId: UInt64, channels: [UInt64],
    registry: ChannelRegistry, schemaSendTracker: SchemaSendTracker,
    schemaReceiveTracker: SchemaTracker, context: RequestContext,
